// 1. Get raw input
const items = $input.all();
let rawData = items[0]?.json || {};
let finalResult = {};

try {
  if (rawData.hasOwnProperty('0')) {
    const combinedString = Object.values(rawData).join('');
    finalResult = JSON.parse(combinedString);
  } else if (rawData.body && typeof rawData.body === 'object') {
    finalResult = rawData.body;
  } else if (typeof rawData.body === 'string') {
    finalResult = JSON.parse(rawData.body);
  } else {
    finalResult = rawData;
  }
} catch (e) {
  finalResult = rawData;
  finalResult._error = "Parsing failed: " + e.message;
}

const output = {
  ...finalResult,
  tenant_id: parseInt(finalResult.tenant_id || 1001),
  day_of_week: parseInt(finalResult.day_of_week ?? -1),
  total_months: parseInt(finalResult.total_months || finalResult.number_of_months || '12'),
  monthly_amount: parseFloat(finalResult.monthly_amount || finalResult.rate_per_month || '0'),
  payment_day: parseInt(finalResult.payment_day || '20'),
  _debug_parsed: true
};

console.log('Parsed data:', output);

return [{ json: output }];

const inputData = $('Debug: Check Input Data').first().json;
const wb = inputData || {};

console.log('Received for Date Gen:', wb);

const specificDates = (wb.specific_dates || '').trim();
const frequency = wb.frequency || 'weekly';
const startDateStr = wb.start_date || '';
const endDateStr = wb.end_date || '';
const dayOfWeek = parseInt(wb.day_of_week ?? '-1');
const ratePerSession = parseFloat(wb.rate_per_session || '0') || 0;
const totalMonths = parseInt(wb.total_months || '12');
const monthlyAmount = parseFloat(wb.monthly_amount || '0') || 0;

if (!startDateStr && !specificDates) {
  return [{ json: { error: "Missing start_date or specific_dates", date_count: 0, dates: "" } }];
}

let dates = [];

if (specificDates) {
  dates = specificDates.split(',').map(d => d.trim()).filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d)).sort();
} else {
  const startDate = new Date(startDateStr + 'T00:00:00Z');
  // Calculate end date based on total months if no explicit end date
  const maxDate = endDateStr ? new Date(endDateStr + 'T00:00:00Z') : new Date(new Date(startDate).setMonth(startDate.getMonth() + totalMonths));

  const dow = dayOfWeek >= 0 ? dayOfWeek : startDate.getUTCDay();
  const daysToAdd = (dow - startDate.getUTCDay() + 7) % 7;

  const cursor = new Date(startDate);
  cursor.setUTCDate(cursor.getUTCDate() + daysToAdd);

  while (cursor <= maxDate && dates.length < 365) {
    dates.push(cursor.toISOString().slice(0, 10));
    if (frequency === 'monthly') cursor.setUTCMonth(cursor.getUTCMonth() + 1);
    else if (frequency === 'fortnightly') cursor.setUTCDate(cursor.getUTCDate() + 14);
    else cursor.setUTCDate(cursor.getUTCDate() + 7);
  }
}

const firstDate = dates[0] ? new Date(dates[0] + 'T00:00:00Z') : null;
const periodStart = firstDate ? new Date(Date.UTC(firstDate.getUTCFullYear(), firstDate.getUTCMonth(), 1)) : null;
const periodEnd = firstDate ? new Date(Date.UTC(firstDate.getUTCFullYear(), firstDate.getUTCMonth() + 1, 0)) : null;

const firstMonthDates = dates.filter(d => {
  const dt = new Date(d + 'T00:00:00Z');
  return dt >= periodStart && dt <= periodEnd;
});

// Calculate monthly payment amount - use provided monthly_amount or calculate from sessions
let firstMonthAmount = monthlyAmount;
if (firstMonthAmount <= 0) {
  // Fallback to rate per session calculation
  firstMonthAmount = firstMonthDates.length * ratePerSession;
}

return [{ json: {
  dates: dates.join(','),
  date_count: dates.length,
  period_start: periodStart ? periodStart.toISOString().slice(0, 10) : '',
  period_end: periodEnd ? periodEnd.toISOString().slice(0, 10) : '',
  first_month_sessions: firstMonthDates.length,
  first_month_amount: firstMonthAmount.toFixed(2),
  first_date: dates[0] || '',
  total_months: totalMonths,
  monthly_amount: monthlyAmount > 0 ? monthlyAmount : firstMonthAmount
} }];

const wb = $('Debug: Check Input Data').first().json;
const customerRow = $('DB: Upsert Customer').first().json;
const dateGen = $('Code: Generate Dates').first().json;

const customer_id = customerRow?.customer_id;
const room_id = wb?.room_id;
const tenant_id = wb?.tenant_id;

console.log("Validation Check:", { customer_id, room_id, tenant_id, date_count: dateGen.date_count });

if (!customer_id) {
  throw new Error("Validation Error: The database did not return a customer_id. Check 'DB: Upsert Customer' output.");
}

if (!room_id || !tenant_id) {
  throw new Error(`Validation Error: Missing Webhook data. Room: ${room_id}, Tenant: ${tenant_id}`);
}

if (!dateGen.dates || dateGen.date_count === 0) {
  throw new Error("Validation Error: No dates were generated for this booking.");
}

return [{
  json: {
    customer_id,
    room_id,
    tenant_id,
    dates: dateGen.dates,
    date_count: dateGen.date_count,
    first_month_amount: dateGen.first_month_amount,
    monthly_amount: dateGen.monthly_amount,
    total_months: dateGen.total_months,
    first_date: dateGen.first_date,
    customer_name: customerRow.full_name || wb.customer_name,
    customer_email: customerRow.email || wb.customer_email
  }
}];
